function printInvoice(sale: Sale, products: Product[]){const names=Object.fromEntries(products.map(p=>[p.variantId||p.id,p.name+" "+(p.size||"")+" "+(p.color||"")]));const s=settingsStorage.get(); void printHtml(invoiceHtml(sale,s,names),s.paper,(s as any).printerName||getSavedPrinterName()).catch(e=>alert(e instanceof Error?e.message:"Printer failed."));}
