 const printTable=(title:string,headers:string[],rows:string[][])=>{const w=window.open("","_blank","width=1000,height=800");if(!w)return;w.document.write("<html><head><title>"+title+"</title><style>body{font-family:Arial;padding:24px}table{width:100%;border-collapse:collapse}th,td{border:1px solid #ddd;padding:8px;text-align:left}h1{margin-bottom:4px}</style></head><body><h1>"+title+"</h1><p>"+from+" to "+to+"</p><table><thead><tr>"+headers.map(h=>"<th>"+h+"</th>").join("")+"</tr></thead><tbody>"+rows.map(row=>"<tr>"+row.map(x=>"<td>"+x+"</td>").join("")+"</tr>").join("")+"</tbody></table><script>window.print()</script></body></html>");w.document.close()};
 const exportCsv=(name:string,headers:string[],rows:string[][])=>{const esc=(x:string)=>'"'+String(x).replace(/"/g,'""')+'"';const csv=[headers,...rows].map(r=>r.map(esc).join(",")).join("\n");const a=document.createElement("a");a.href=URL.createObjectURL(new Blob([csv],{type:"text/csv"}));a.download=name+".csv";a.click();URL.revokeObjectURL(a.href)};
 return <><section className="panel"><h2>Reports</h2><div className="buttonrow"><button onClick={()=>{const d=new Date();setFrom(new Date(d.getFullYear(),d.getMonth(),d.getDate()).toISOString().slice(0,10));setTo(d.toISOString().slice(0,10))}}>Today</button><button onClick={()=>{const d=new Date();setFrom(new Date(d.getTime()-6*86400000).toISOString().slice(0,10));setTo(d.toISOString().slice(0,10))}}>Last 7 Days</button><button onClick={()=>{const d=new Date();setFrom(new Date(d.getFullYear(),d.getMonth(),1).toISOString().slice(0,10));setTo(d.toISOString().slice(0,10))}}>This Month</button><button onClick={()=>{const d=new Date();setFrom(new Date(d.getFullYear(),0,1).toISOString().slice(0,10));setTo(d.toISOString().slice(0,10))}}>This Year</button></div><div className="formgrid"><label>FROM<input type="date" value={from} onChange={e=>setFrom(e.target.value)}/></label><label>TO<input type="date" value={to} onChange={e=>setTo(e.target.value)}/></label></div><button className="primary" onClick={load} disabled={busy}>{busy?"Loading...":"Refresh Reports"}</button>{error&&<p>{error}</p>}</section>
 {summary&&<div className="grid">{[["Sales","Rs. "+Number(summary.sales?.sales_total||0).toFixed(2)],["Invoices",String(summary.sales?.invoices||0)],["Discounts","Rs. "+Number(summary.sales?.discounts||0).toFixed(2)],["Gross Profit","Rs. "+Number(summary.profit?.gross_profit||0).toFixed(2)],["Inventory Cost","Rs. "+Number(summary.inventory?.cost_value||0).toFixed(2)],["Retail Value","Rs. "+Number(summary.inventory?.retail_value||0).toFixed(2)]].map(([a,b])=><section className="card" key={a}><span>{a}</span><strong>{b}</strong></section>)}</div>}
 {sales&&<><section className="panel"><div className="formgrid"><label>Payment Filter<select value={salesFilter} onChange={e=>setSalesFilter(e.target.value)}><option value="all">All</option>{payments.map(x=><option key={x.method} value={x.method}>{x.method}</option>)}</select></label><label>Category Filter<select value={categoryFilter} onChange={e=>setCategoryFilter(e.target.value)}><option value="all">All</option>{(sales?.categories||[]).map((x:any)=><option key={x.category} value={x.category}>{x.category}</option>)}</select></label><label>Cashier Filter<select value={cashierFilter} onChange={e=>setCashierFilter(e.target.value)}><option value="all">All</option>{(sales?.cashiers||[]).map((x:any)=><option key={x.cashier} value={x.cashier}>{x.cashier}</option>)}</select></label></div><h2>Payment Method Breakdown</h2><table><thead><tr><th>Method</th><th>Transactions</th><th>Total</th></tr></thead><tbody>{payments.filter(x=>salesFilter==="all"||x.method===salesFilter).map(x=><tr key={x.method}><td>{x.method}</td><td>{x.transactions}</td><td>Rs. {Number(x.total||0).toFixed(2)}</td></tr>)}</tbody></table></section><section className="panel"><h2>Returns / Exchange Profit Impact</h2>{returnImpact&&<div className="grid">{[["Returned Sales","Rs. "+Number(returnImpact.returned_sales||0).toFixed(2)],["Returned Cost","Rs. "+Number(returnImpact.returned_cost||0).toFixed(2)],["Exchange Sales","Rs. "+Number(returnImpact.exchange_sales||0).toFixed(2)],["Exchange Cost","Rs. "+Number(returnImpact.exchange_cost||0).toFixed(2)],["Net Sales Impact","Rs. "+Number(returnImpact.net_sales_impact||0).toFixed(2)],["Gross Profit Impact","Rs. "+Number(returnImpact.gross_profit_impact||0).toFixed(2)],["Transactions",String(returnImpact.transactions||0)]].map(([k,v])=><section className="card" key={k}><span>{k}</span><strong>{v}</strong></section>)}</div>}</section><section className="panel"><h2>Profit Analysis</h2>{profit&&<><div className="grid">{[["Gross Sales","Rs. "+Number(profit.summary.gross_sales||0).toFixed(2)],["Discounts","Rs. "+Number(profit.summary.discounts||0).toFixed(2)],["Net Sales","Rs. "+Number(profit.summary.net_sales||0).toFixed(2)],["COGS","Rs. "+Number(profit.summary.cogs||0).toFixed(2)],["Gross Profit","Rs. "+Number(profit.summary.gross_profit||0).toFixed(2)],["Margin",Number(profit.summary.margin_percent||0).toFixed(2)+"%"]].map(([k,v])=><section className="card" key={k}><span>{k}</span><strong>{v}</strong></section>)}</div><button onClick={()=>exportSalesExcel(profit.daily as any)}>Export Profit Excel</button><button onClick={()=>printTable("Profit Report",["Date","Gross Sales","Discounts","Net Sales","COGS","Gross Profit","Margin %"],profit.daily.map((x:any)=>[x.date,"Rs. "+x.gross_sales,"Rs. "+x.discounts,"Rs. "+x.net_sales,"Rs. "+x.cogs,"Rs. "+x.gross_profit,x.margin_percent+"%"]))}>Print Profit Report</button></>}</section><section className="panel"><h2>Sales by Day</h2><button onClick={()=>exportSalesExcel((sales?.daily||[]).map((x:any)=>({Date:x.date,Invoices:x.invoices,Sales:x.total,Discounts:x.discounts})))}>Export Excel</button> <button onClick={()=>exportCsv("sales-report",["Date","Invoices","Sales","Discounts"],sales.daily.map((x:any)=>[x.date,x.invoices,x.total,x.discounts]))}>Export CSV</button> <button onClick={()=>printTable("Sales Report",["Date","Invoices","Sales","Discounts"],sales.daily.map((x:any)=>[x.date,String(x.invoices),"Rs. "+x.total,"Rs. "+x.discounts]))}>Print</button><table><thead><tr><th>Date</th><th>Invoices</th><th>Sales</th><th>Discounts</th></tr></thead><tbody>{sales.daily.map((x:any)=><tr key={x.date}><td>{x.date}</td><td>{x.invoices}</td><td>Rs. {x.total}</td><td>Rs. {x.discounts}</td></tr>)}</tbody></table><h3>Payment Methods</h3><table><thead><tr><th>Method</th><th>Invoices</th><th>Total</th></tr></thead><tbody>{sales.payments.map((x:any)=><tr key={x.method}><td>{x.method}</td><td>{x.invoices}</td><td>Rs. {x.total}</td></tr>)}</tbody></table></section></>}
 <section className="panel"><h2>Category Performance</h2><table><thead><tr><th>Category</th><th>Units</th><th>Sales</th><th>Cost</th><th>Gross Profit</th></tr></thead><tbody>{(sales?.categories||[]).filter((x:any)=>categoryFilter==="all"||x.category===categoryFilter).map((x:any)=><tr key={x.category}><td>{x.category}</td><td>{x.units}</td><td>Rs. {x.sales}</td><td>Rs. {x.cost}</td><td>Rs. {x.gross_profit}</td></tr>)}</tbody></table><h2>Cashier Performance</h2><table><thead><tr><th>Cashier</th><th>Invoices</th><th>Sales</th><th>Discounts</th></tr></thead><tbody>{(sales?.cashiers||[]).filter((x:any)=>cashierFilter==="all"||x.cashier===cashierFilter).map((x:any)=><tr key={x.cashier}><td>{x.cashier}</td><td>{x.invoices}</td><td>Rs. {x.sales}</td><td>Rs. {x.discounts}</td></tr>)}</tbody></table></section><section className="panel"><h2>Product Performance</h2><button onClick={()=>exportCsv("product-report",["Product","SKU","Size","Color","Units","Sales","Cost","Gross Profit"],products.map(x=>[x.name,x.sku,x.size||"",x.color||"",x.units,x.sales,x.cost,x.gross_profit]))}>Export CSV</button> <button onClick={()=>printTable("Product Report",["Product","SKU","Size","Color","Units","Sales","Cost","Profit"],products.map(x=>[x.name,x.sku,x.size||"",x.color||"",String(x.units),"Rs. "+x.sales,"Rs. "+x.cost,"Rs. "+x.gross_profit]))}>Print</button><table><thead><tr><th>Product</th><th>SKU</th><th>Size</th><th>Color</th><th>Units</th><th>Sales</th><th>Gross Profit</th></tr></thead><tbody>{products.map((x:any)=><tr key={x.sku+"-"+x.size+"-"+x.color}><td>{x.name}</td><td>{x.sku}</td><td>{x.size||"—"}</td><td>{x.color||"—"}</td><td>{x.units}</td><td>Rs. {x.sales}</td><td>Rs. {x.gross_profit}</td></tr>)}</tbody></table></section>
 <section className="panel"><h2>Purchases</h2><button onClick={()=>exportCsv("purchase-report",["Invoice","Supplier","Date","Total"],purchases.map(x=>[x.invoice_no,x.supplier||"",x.purchase_date,x.total]))}>Export CSV</button><table><thead><tr><th>Invoice</th><th>Supplier</th><th>Date</th><th>Total</th></tr></thead><tbody>{purchases.map(x=><tr key={x.invoice_no}><td>{x.invoice_no}</td><td>{x.supplier||"—"}</td><td>{new Date(x.purchase_date).toLocaleString()}</td><td>Rs. {x.total}</td></tr>)}</tbody></table></section>
 <section className="panel"><h2>Khata / Outstanding</h2><button onClick={()=>exportCsv("khata-report",["Customer","Phone","Balance","Credit Limit"],khata.map(x=>[x.name,x.phone||"",x.balance,x.credit_limit]))}>Export CSV</button><button onClick={()=>printTable("Khata Report",["Customer","Phone","Balance","Credit Limit"],khata.map(x=>[x.name,x.phone||"","Rs. "+x.balance,"Rs. "+x.credit_limit]))}>Print</button><table><thead><tr><th>Customer</th><th>Phone</th><th>Outstanding</th><th>Credit Limit</th></tr></thead><tbody>{khata.map(x=><tr key={x.id}><td>{x.name}</td><td>{x.phone||"—"}</td><td>Rs. {x.balance}</td><td>Rs. {x.credit_limit}</td></tr>)}</tbody></table></section></>
